style.css:
/* Pink Global Typography ? */

/* Main text */
body {
  color: #D98FA8 !important;
  font-family: Arial, sans-serif !important;
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
  color: #E68BAA !important;
}

/* Paragraphs and text */
p, span, label, li {
  color: #D99AAF !important;
}

/* Links */
a {
  color: #F09AB8 !important;
}

/* Bold text */
b, strong {
  color: #C76F91 !important;
}

/* Italic text */
i, em {
  color: #E6A1BA !important;
}

/* Buttons */
button {
  color: #E68BAA !important;
}

/* Text selection */
::selection {
  background: #F4B6C7 !important;
  color: #713D50 !important;
}
